-- v1 to grocery v3; executed in a Room migration transaction.
CREATE TABLE products_v3 (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, name TEXT, sku TEXT, batchNo TEXT, category TEXT, quantity REAL NOT NULL, expiryDate INTEGER, barcode TEXT, brand TEXT, unit TEXT, location TEXT, dateType TEXT, received REAL NOT NULL, lowStock REAL NOT NULL, receivedDay INTEGER NOT NULL, archived INTEGER NOT NULL);
INSERT INTO products_v3 SELECT id,name,CASE WHEN sku IS NULL OR TRIM(sku)='' THEN 'LEGACY-'||id ELSE sku END,batchNo,CASE category WHEN 'Dairy' THEN 'Dairy and Eggs' WHEN 'Bakery' THEN 'Bread and Bakery' WHEN 'Pantry' THEN 'Packaged Foods' ELSE category END,quantity,expiryDate,'','','pieces','Verify location','Expiry',quantity,5,0,0 FROM products;
DROP TABLE products;
ALTER TABLE products_v3 RENAME TO products;
CREATE INDEX index_products_sku ON products(sku);
CREATE INDEX index_products_name ON products(name);
CREATE INDEX index_products_batchNo ON products(batchNo);
CREATE TABLE grocery_staff (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, name TEXT, email TEXT, salt TEXT, passwordHash TEXT);
CREATE UNIQUE INDEX index_grocery_staff_email ON grocery_staff(email);
CREATE TABLE grocery_movements (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, batchId INTEGER NOT NULL, staffId INTEGER NOT NULL, time INTEGER NOT NULL, delta REAL NOT NULL, reason TEXT, note TEXT, staffName TEXT, reversalOf INTEGER, FOREIGN KEY(batchId) REFERENCES products(id) ON UPDATE NO ACTION ON DELETE NO ACTION, FOREIGN KEY(staffId) REFERENCES grocery_staff(id) ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE INDEX index_grocery_movements_batchId ON grocery_movements(batchId);
CREATE INDEX index_grocery_movements_staffId ON grocery_movements(staffId);
CREATE UNIQUE INDEX index_grocery_movements_reversalOf ON grocery_movements(reversalOf);
CREATE TABLE grocery_reminders (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, batchId INTEGER NOT NULL, createdDay INTEGER NOT NULL, milestone INTEGER NOT NULL, FOREIGN KEY(batchId) REFERENCES products(id) ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE INDEX index_grocery_reminders_batchId ON grocery_reminders(batchId);
CREATE UNIQUE INDEX index_grocery_reminders_batchId_milestone ON grocery_reminders(batchId,milestone);
ALTER TABLE grocery_staff ADD COLUMN phone TEXT;
ALTER TABLE grocery_staff ADD COLUMN photoPath TEXT;
ALTER TABLE products ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0;
ALTER TABLE products ADD COLUMN photoPath TEXT;
ALTER TABLE products ADD COLUMN description TEXT;
ALTER TABLE products ADD COLUMN packSize TEXT;
ALTER TABLE products ADD COLUMN variation TEXT;
CREATE TABLE product_catalog (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, sku TEXT NOT NULL, name TEXT, barcode TEXT, brand TEXT, category TEXT, unit TEXT, description TEXT, packSize TEXT, variation TEXT, photoPath TEXT, lowStock REAL NOT NULL, archived INTEGER NOT NULL, deleted INTEGER NOT NULL);
CREATE UNIQUE INDEX index_product_catalog_sku ON product_catalog(sku);
INSERT INTO product_catalog(sku,name,barcode,brand,category,unit,description,packSize,variation,photoPath,lowStock,archived,deleted) SELECT sku,name,barcode,brand,category,unit,description,packSize,variation,photoPath,lowStock,archived,deleted FROM products WHERE id IN (SELECT MIN(id) FROM products GROUP BY sku);
ALTER TABLE products ADD COLUMN productId INTEGER REFERENCES product_catalog(id) ON UPDATE NO ACTION ON DELETE NO ACTION;
CREATE INDEX index_products_productId ON products(productId);
UPDATE products SET productId=(SELECT id FROM product_catalog WHERE product_catalog.sku=products.sku);
ALTER TABLE grocery_movements ADD COLUMN unit TEXT;
UPDATE grocery_movements SET unit=(SELECT unit FROM products WHERE products.id=grocery_movements.batchId);
ALTER TABLE products ADD COLUMN measurementValue TEXT;
ALTER TABLE products ADD COLUMN measurementUnit TEXT;
ALTER TABLE product_catalog ADD COLUMN measurementValue TEXT;
ALTER TABLE product_catalog ADD COLUMN measurementUnit TEXT;
ALTER TABLE products ADD COLUMN stockReference TEXT COLLATE NOCASE;
UPDATE products SET stockReference='B'||id;
CREATE UNIQUE INDEX index_products_productId_stockReference ON products(productId,stockReference);
CREATE TABLE saved_options (kind TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(kind,value));
INSERT OR IGNORE INTO saved_options SELECT 'category',category FROM product_catalog WHERE category IS NOT NULL AND TRIM(category)<>'';
INSERT OR IGNORE INTO saved_options SELECT 'unit',measurementUnit FROM product_catalog WHERE measurementUnit IS NOT NULL AND TRIM(measurementUnit)<>'';
DELETE FROM grocery_reminders WHERE batchId IN (SELECT id FROM products WHERE productId IN (SELECT id FROM product_catalog WHERE lower(trim(replace(replace(replace(replace(category,'  ',' '),'  ',' '),'  ',' '),'  ',' '))) IN ('toiletries','household products')) OR (productId IS NULL AND lower(trim(replace(replace(replace(replace(category,'  ',' '),'  ',' '),'  ',' '),'  ',' '))) IN ('toiletries','household products')));
DELETE FROM grocery_movements WHERE batchId IN (SELECT id FROM products WHERE productId IN (SELECT id FROM product_catalog WHERE lower(trim(replace(replace(replace(replace(category,'  ',' '),'  ',' '),'  ',' '),'  ',' '))) IN ('toiletries','household products')) OR (productId IS NULL AND lower(trim(replace(replace(replace(replace(category,'  ',' '),'  ',' '),'  ',' '),'  ',' '))) IN ('toiletries','household products')));
DELETE FROM products WHERE id IN (SELECT id FROM products WHERE productId IN (SELECT id FROM product_catalog WHERE lower(trim(replace(replace(replace(replace(category,'  ',' '),'  ',' '),'  ',' '),'  ',' '))) IN ('toiletries','household products')) OR (productId IS NULL AND lower(trim(replace(replace(replace(replace(category,'  ',' '),'  ',' '),'  ',' '),'  ',' '))) IN ('toiletries','household products')));
DELETE FROM product_catalog WHERE lower(trim(replace(replace(replace(replace(category,'  ',' '),'  ',' '),'  ',' '),'  ',' '))) IN ('toiletries','household products');
DELETE FROM saved_options WHERE kind='category' AND lower(trim(replace(replace(replace(replace(value,'  ',' '),'  ',' '),'  ',' '),'  ',' '))) IN ('toiletries','household products','grains and cereals','flakes','others');
DELETE FROM saved_options WHERE rowid NOT IN (SELECT min(rowid) FROM saved_options GROUP BY kind,lower(trim(replace(replace(replace(replace(value,'  ',' '),'  ',' '),'  ',' '),'  ',' '))));
